# gam3shell[kind=1..2, l=0..3] from gfn2.f90:44-46.
_GFN2_GAM3SHELL = (
    (1.0, 1.0, 0.5, 0.25),    # kind=1 (main-group)   for l=0,1,2,3 → s,p,d,f
    (1.0, 0.5, 0.25, 0.25),   # kind=2 (TM)
)
# Note: the Fortran reshape uses dim1=2 (kind), dim2=4 (l). The order
# of the flat list `[1.0, 1.0, 0.5, 0.5, 0.25, 0.25, 0.25, 0.25]` fills
# *column-major*: (kind=1,l=0)=1.0, (kind=2,l=0)=1.0, (kind=1,l=1)=0.5,
# (kind=2,l=1)=0.5, (kind=1,l=2)=0.25, (kind=2,l=2)=0.25, (kind=1,l=3)=0.25,
# (kind=2,l=3)=0.25. So both kinds end up identical at l=2,3 = 0.25; for
# l=1 both are 0.5. Wait — that's NOT what I have above. Let me recheck.
#
# Reading gfn2.f90:44-46 again:
#   gam3shell(2, 0:3) = reshape(
#     [1.0, 1.0, 0.5, 0.5, 0.25, 0.25, 0.25, 0.25],
#     shape(gam3shell))
#
# Fortran column-major fills the (kind, l) array as kind=1..2 fast,
# l=0..3 slow. So:
#   l=0: kind=1 → 1.0, kind=2 → 1.0
#   l=1: kind=1 → 0.5, kind=2 → 0.5
#   l=2: kind=1 → 0.25, kind=2 → 0.25
#   l=3: kind=1 → 0.25, kind=2 → 0.25
# i.e. shell-resolved scaling depends ONLY on l, not on kind.
_GFN2_GAM3SHELL = (
    (1.0, 0.5, 0.25, 0.25),   # kind=1: s, p, d, f
    (1.0, 0.5, 0.25, 0.25),   # kind=2: same
)


@dataclass(frozen=True)
class GFN2Globals:
    """GFN2-xTB global Hamiltonian / SCF parameters (gfn2.f90:50-66)."""
    ks: float = 1.85
    kp: float = 2.23
    kd: float = 2.23
    kf: float = 2.23
    ksp: float = 0.5 * (1.85 + 2.23)   # h0scal default for s-p (no override)
    ksd: float = 2.0                   # explicit s-d coupling
    kpd: float = 2.0                   # explicit p-d coupling
    kdiff: float = 2.0
    enshell: float = 2.0
    ipeashift: float = 1.78069 * 0.1
    aesshift: float = 1.2
    aesexp: float = 4.0
    aesrmax: float = 5.0
    alphaj: float = 2.0
    aesdmp3: float = 3.0
    aesdmp5: float = 4.0
    wexp: float = 0.5
    # repulsion
    kexp: float = 1.5
    kexp_light: float = 1.0
    rexp: float = 1.0
    # D4 damping
    d4_s6: float = 1.0
    d4_s8: float = 2.7
    d4_a1: float = 0.52
    d4_a2: float = 5.0
    d4_s9: float = 5.0


GFN2_GLOBALS = GFN2Globals()


@dataclass(frozen=True)
class GFN2Shell:
    """One shell on a GFN2 element."""
    l: int
    n: int
    h: float                # selfEnergy in eV
    zeta: float             # Slater exponent
    k_poly: float           # shellPoly[l, Z]
    shell_hardness: float   # shellHardness[l, Z]
    kcn: float              # kCN[l, Z] — already in eV/CN units (no extra ×0.01)


@dataclass(frozen=True)
class GFN2ElementParams:
    """Per-element block for GFN2."""
    Z: int
    symbol: str
    shells: tuple[GFN2Shell, ...]
    en: float                     # Pauling electronegativity
    chemical_hardness: float      # GAM (atomic part)
    third_order: float            # thirdOrderAtom (already × 0.1)
    rep_alpha: float              # REPA
    rep_zeff: float               # REPB
    dip_kernel: float             # AES dipole kernel
    quad_kernel: float            # AES quadrupole kernel
    kind: int                     # gfn2Kinds(Z) ∈ {1, 2}


_ELEMENT_SYMBOLS = (
    "H","He","Li","Be","B","C","N","O","F","Ne",
    "Na","Mg","Al","Si","P","S","Cl","Ar","K","Ca",
    "Sc","Ti","V","Cr","Mn","Fe","Co","Ni","Cu","Zn",
    "Ga","Ge","As","Se","Br","Kr","Rb","Sr","Y","Zr",
    "Nb","Mo","Tc","Ru","Rh","Pd","Ag","Cd","In","Sn",
    "Sb","Te","I","Xe","Cs","Ba","La","Ce","Pr","Nd",
    "Pm","Sm","Eu","Gd","Tb","Dy","Ho","Er","Tm","Yb",
    "Lu","Hf","Ta","W","Re","Os","Ir","Pt","Au","Hg",
    "Tl","Pb","Bi","Po","At","Rn",
)
assert len(_ELEMENT_SYMBOLS) == 86


def _build_element(Z: int) -> GFN2ElementParams:
    n_sh = _GFN2_NSHELL[Z]
    shells = []
    for ish in range(n_sh):
        l = _GFN2_ANGSHELL[Z][ish]
        n = _GFN2_PRINCIPALQUANTUMNUMBER[Z][ish]
        h = _GFN2_SELFENERGY[Z][ish]
        zeta = _GFN2_SLATEREXPONENT[Z][ish]
        # shellPoly is per-l (shape (4, Z) in Fortran).
        k_poly = _GFN2_SHELLPOLY[Z][l]
        sh_hard = _GFN2_SHELLHARDNESS[Z][l]
        kcn = _GFN2_KCN[Z][l]
        shells.append(GFN2Shell(
            l=int(l), n=int(n), h=float(h), zeta=float(zeta),
            k_poly=float(k_poly), shell_hardness=float(sh_hard),
            kcn=float(kcn),
        ))
    return GFN2ElementParams(
        Z=Z,
        symbol=_ELEMENT_SYMBOLS[Z - 1],
        shells=tuple(shells),
        en=float(_GFN2_PAULING_EN[Z]),
        chemical_hardness=float(_GFN2_CHEMICALHARDNESS[Z]),
        third_order=float(_GFN2_THIRDORDERATOM[Z]),
        rep_alpha=float(_GFN2_REPALPHA[Z]),
        rep_zeff=float(_GFN2_REPZEFF[Z]),
        # gfn2.f90 has trailing ``* 0.01_wp`` on both dipKernel and
        # quadKernel arrays (lines 270, 291). Our extractor missed the
        # scaling — apply it here.
        dip_kernel=float(_GFN2_DIPKERNEL[Z]) * 0.01,
        quad_kernel=float(_GFN2_QUADKERNEL[Z]) * 0.01,
        kind=int(_GFN2_KINDS[Z]),
    )


GFN2_PARAMS: dict[int, GFN2ElementParams] = {
    Z: _build_element(Z) for Z in range(1, 87)
}


